    import numpy as np
    if s is None: return np.nan
    s=str(s).strip()
    if s=='' or s.lower() in {'nan','none','null'}: return np.nan
    s=s.replace(' ','')
    if ',' in s and '.' in s:
        if s.rfind(',')>s.rfind('.'):
            s=s.replace('.','').replace(',','.')
        else:
