import pandas as pd, numpy as np
raw=pd.read_csv('/root/environment/data/ckd_lab_data.csv', dtype=str)

def parse(s):
    if s is None: return np.nan
    s=str(s).strip()
    if s=='' or s.lower() in {'nan','none','null'}: return np.nan
    s=s.replace(' ','')
    if ',' in s and '.' in s:
        if s.rfind(',')>s.rfind('.'):
            s=s.replace('.','').replace(',','.')
        else:
            s=s.replace(',','')
    elif ',' in s:
        s=s.replace(',','.')
    try:
        return float(s)
    except:
        return np.nan

num_cols=[c for c in raw.columns if c!='patient_id']
rows=[]
for c in num_cols:
    col=raw[c].map(parse)
    col=col.dropna()
    if col.empty:
        continue
    q1,q99=np.percentile(col,[1,99])
    rows.append((c,float(col.min()),float(q1),float(np.percentile(col,50)),float(q99),float(col.max())))

# print sorted by max descending
rows_sorted=sorted(rows, key=lambda x: x[5], reverse=True)
for c,mi,q1,med,q99,ma in rows_sorted[:30]:
    print(f"{c:35s} min={mi:.4g} p1={q1:.4g} med={med:.4g} p99={q99:.4g} max={ma:.4g}")
print('...')
for c,mi,q1,med,q99,ma in rows_sorted[-15:]:
    print(f"{c:35s} min={mi:.4g} p1={q1:.4g} med={med:.4g} p99={q99:.4g} max={ma:.4g}")
PY"}

