import pandas as pd, numpy as np, re
path='/root/environment/data/ckd_lab_data.csv'
raw=pd.read_csv(path, dtype=str)

num_cols=[c for c in raw.columns if c!='patient_id']

def parse_val(x):
    if x is None or (isinstance(x,float) and np.isnan(x)):
        return np.nan
    s=str(x).strip()
    if s=='' or s.lower() in {'nan','none','null'}:
        return np.nan
    # remove spaces
    s=s.replace(' ','')
    # if both '.' and ',' decide if comma thousands
    if ',' in s and '.' in s:
        # if last comma after last dot -> comma decimal, dots thousands
        if s.rfind(',')>s.rfind('.'):
            s=s.replace('.','')
            s=s.replace(',','.')
        else:
            s=s.replace(',','')
    elif ',' in s:
        s=s.replace(',','.')
    try:
        return float(s)
    except:
        return np.nan

parsed=raw.copy()
for c in num_cols:
    parsed[c]=raw[c].map(parse_val)

# count missing per column
miss=parsed[num_cols].isna().mean().sort_values(ascending=False)
print('Top missing columns (fraction):')
print(miss.head(10))

# basic min/max and 1/99 percentiles for select columns that often have unit issues
suspects=['Serum_Creatinine','Hemoglobin','Albumin_Serum','Total_Protein','Serum_Calcium','Ionized_Calcium','Phosphorus','Magnesium','Glucose','Total_Cholesterol','LDL_Cholesterol','HDL_Cholesterol','Triglycerides','Uric_Acid','Total_Bilirubin','Direct_Bilirubin','Vitamin_D_25OH','Vitamin_D_1_25OH','CRP','Troponin_I','Troponin_T','Free_T4','Free_T3']
for c in suspects:
    if c not in parsed.columns: continue
    col=parsed[c].dropna()
    if col.empty: continue
    q1,q99=np.percentile(col,[1,99])
    print(f"{c:30s} min={col.min():.4g} p1={q1:.4g} p99={q99:.4g} max={col.max():.4g} mean={col.mean():.4g}")
PY"}

